import {json,requireBoss} from '../../../_lib.js';import {ensureDatabase} from '../../../_schema.js';
async function schema(env){await env.DB.prepare(`CREATE TABLE IF NOT EXISTS bundle_preview_revisions(id INTEGER PRIMARY KEY AUTOINCREMENT,bundle_product_id INTEGER NOT NULL,old_cover_url TEXT NOT NULL,old_preview_urls TEXT NOT NULL,new_cover_url TEXT NOT NULL,new_preview_urls TEXT NOT NULL,changed_by INTEGER NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP)`).run()}
export async function onRequestGet(ctx){await ensureDatabase(ctx.env);await schema(ctx.env);const auth=await requireBoss(ctx);if(auth.error)return auth.error;const items=(await ctx.env.DB.prepare(`SELECT p.id,p.slug,p.title,p.cover_url,p.preview_urls,p.status,p.created_at,COUNT(b.source_product_id) member_count,(SELECT COUNT(*) FROM bundle_preview_revisions r WHERE r.bundle_product_id=p.id) revision_count FROM products p JOIN product_bundle_items b ON b.bundle_product_id=p.id WHERE p.deleted_at IS NULL GROUP BY p.id ORDER BY p.id DESC`).all()).results||[];return json({items:items.map(item=>({...item,preview_urls:JSON.parse(item.preview_urls||'[]')}))},200,{'cache-control':'private, no-store'})}
